const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const receipts = [];
  const service = new PaymentService(ledger, {
    acknowledge: async r => { receipts.push(r); },
  });
  const original = await service.pay('shop', 'sale', 123);
  assert.deepEqual(original, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
  assert.equal(await service.pay('shop', 'sale', 123), original);
  assert.equal(ledger.entries.length, 1);
  assert.equal(receipts.length, 2);
  await assert.rejects(service.pay('shop', 'sale', 124), { message: 'key conflict' });
  assert.equal(ledger.entries.length, 1);
  assert.equal(receipts.length, 2);
  assert.notEqual(await service.pay('other', 'sale', 124), original);
  assert.notEqual(await service.pay('shop', 'other', 123), original);
  // Tenant/key pairs must not collide when their strings contain separators.
  await service.pay('a:b', 'c', 10);
  await service.pay('a', 'b:c', 20);
  assert.equal(ledger.entries.length, 5);

  const concurrentLedger = new Ledger();
  let release;
  const gate = new Promise(resolve => { release = resolve; });
  const concurrentReceipts = [];
  const concurrent = new PaymentService(concurrentLedger, {
    acknowledge: async r => { concurrentReceipts.push(r); await gate; },
  });
  const first = concurrent.pay('shop', 'sale', 123);
  const second = concurrent.pay('shop', 'sale', 123);
  await assert.rejects(concurrent.pay('shop', 'sale', 124), { message: 'key conflict' });
  assert.equal(concurrentLedger.entries.length, 1);
  assert.equal(concurrentReceipts.length, 2);
  assert.equal(concurrentReceipts[0], concurrentReceipts[1]);
  release();
  const results = await Promise.all([first, second]);
  assert.equal(results[0], results[1]);

  for (const attempts of [1, 2, 3, 4, 5]) {
    const retryLedger = new Ledger();
    let applies = 0;
    const apply = retryLedger.apply.bind(retryLedger);
    retryLedger.apply = (...args) => { applies++; return apply(...args); };
    const forwarded = [];
    const failures = Array.from({ length: attempts }, (_, i) => new Transient(`failure ${i}`));
    const retryService = new PaymentService(retryLedger, {
      acknowledge: async r => {
        forwarded.push(r);
        throw failures[forwarded.length - 1];
      },
    });
    await assert.rejects(retryService.pay('shop', 'sale', 123, attempts),
      error => error === failures[attempts - 1]);
    assert.equal(forwarded.length, attempts);
    assert.ok(forwarded.every(r => r === retryLedger.entries[0]));
    assert.equal(retryLedger.entries.length, 1);
    assert.equal(applies, 1);
  }

  const successLedger = new Ledger();
  const forwarded = [];
  const retrySuccess = new PaymentService(successLedger, {
    acknowledge: async r => {
      forwarded.push(r);
      if (forwarded.length < 3) throw new Transient('retry');
    },
  });
  const success = await retrySuccess.pay('shop', 'sale', 123);
  assert.equal(forwarded.length, 3);
  assert.ok(forwarded.every(r => r === success));
  assert.equal(successLedger.entries.length, 1);

  const fatal = new Error('fatal');
  let fatalCalls = 0;
  const fatalLedger = new Ledger();
  const fatalService = new PaymentService(fatalLedger, {
    acknowledge: async () => { fatalCalls++; throw fatal; },
  });
  await assert.rejects(fatalService.pay('shop', 'sale', 123), error => error === fatal);
  assert.equal(fatalCalls, 1);
  assert.equal(fatalLedger.entries.length, 1);

  const invalidPayments = [
    ['', 'key', 1], ['tenant', '', 1], [null, 'key', 1], ['tenant', 1, 1],
    ['tenant', 'key', 0], ['tenant', 'key', -1], ['tenant', 'key', 1.5],
    ['tenant', 'key', NaN], ['tenant', 'key', Infinity], ['tenant', 'key', '1'],
    ...[0, -1, 6, 1.5, NaN, Infinity, '3', null].map(n => ['tenant', 'key', 1, n]),
  ];
  let actions = 0;
  const validationLedger = new Ledger();
  validationLedger.apply = async () => { actions++; throw new Error('unexpected action'); };
  const validationService = new PaymentService(validationLedger, {
    acknowledge: async () => { actions++; },
  });
  for (const args of invalidPayments) {
    await assert.rejects(validationService.pay(...args), { message: 'invalid payment' });
  }
  assert.equal(actions, 0);

  const directLedger = new Ledger();
  for (const args of invalidPayments.filter(args => args.length === 3)) {
    await assert.rejects(directLedger.apply(...args), { message: 'invalid payment' });
  }
  assert.equal(directLedger.entries.length, 0);
  const directResults = await Promise.all(Array.from({ length: 10 }, () =>
    directLedger.apply('tenant', 'key', 1)));
  assert.ok(directResults.every(r => r === directResults[0]));
  await assert.rejects(directLedger.apply('tenant', 'key', 2), { message: 'key conflict' });
  assert.equal(directLedger.entries.length, 1);
}
module.exports = main();

